## repro/src/main.rs (path deps per tree, feature extensions-draft)
```rust
//! Minimal repro for mimid-1wgh.4.42: OpenMLS enforces only part of
//! draft-ietf-mls-extensions-10 §4.7 AppDataUpdate validation on the
//! RECEIVER side.
//!
//! Two members, alice (committer) and bob (receiver). The group requires
//! the AppDataUpdate proposal type and app_data_dictionary extension.
//! Before each case, components X and Y are seeded with data; Z has none.
//!
//! The receiving application is deliberately naive. It applies each
//! AppDataUpdate proposal in the order OpenMLS hands them over (update ->
//! set, remove -> remove) and relies on OpenMLS to reject proposal lists
//! that §4.7 calls invalid. A case counts as ACCEPTED when bob's
//! `stage_app_data_commit` succeeds and the staged commit merges.

use openmls::component::ComponentData;
use openmls::prelude::tls_codec::{Deserialize as _, Serialize as _};
use openmls::prelude::*;
use openmls_basic_credential::SignatureKeyPair;
use openmls_rust_crypto::OpenMlsRustCrypto;

const CS: Ciphersuite = Ciphersuite::MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519;
/// Private-use component ids (mls-extensions-10 §7.5).
const X: u16 = 0x8001;
const Y: u16 = 0x8002;
const Z: u16 = 0x8003;

/// What the receiver gets: the TLS wire bytes, decoded.
fn wire(out: &MlsMessageOut) -> MlsMessageIn {
    MlsMessageIn::tls_deserialize_exact(out.tls_serialize_detached().unwrap()).unwrap()
}

struct Party {
    provider: OpenMlsRustCrypto,
    signer: SignatureKeyPair,
}

fn party(name: &[u8]) -> (Party, CredentialWithKey) {
    let provider = OpenMlsRustCrypto::default();
    let signer = SignatureKeyPair::new(CS.signature_algorithm()).unwrap();
    signer.store(provider.storage()).unwrap();
    let cwk = CredentialWithKey {
        credential: BasicCredential::new(name.to_vec()).into(),
        signature_key: signer.public().into(),
    };
    (Party { provider, signer }, cwk)
}

fn caps() -> Capabilities {
    Capabilities::new(
        None,
        Some(&[CS]),
        Some(&[ExtensionType::AppDataDictionary]),
        Some(&[ProposalType::AppDataUpdate]),
        Some(&[CredentialType::Basic]),
    )
}

/// The naive receiving/sending application: apply every proposal in the
/// order given, without any §4.7 checks of its own.
fn naive_updates<'a>(
    mut updater: AppDataDictionaryUpdater<'_>,
    proposals: impl Iterator<Item = &'a AppDataUpdateProposal>,
) -> Option<AppDataUpdates> {
    for p in proposals {
        match p.operation() {
            AppDataUpdateOperation::Update(data) => {
                updater.set(ComponentData::from_parts(p.component_id(), data.clone()))
            }
            AppDataUpdateOperation::Remove => updater.remove(&p.component_id()),
        }
    }
    updater.changes()
}

struct Group {
    alice: Party,
    alice_group: MlsGroup,
    bob: Party,
    bob_group: MlsGroup,
}

fn setup() -> Group {
    let (alice, alice_cwk) = party(b"alice");
    let (bob, bob_cwk) = party(b"bob");
    let required = Extension::RequiredCapabilities(RequiredCapabilitiesExtension::new(
        &[ExtensionType::AppDataDictionary],
        &[ProposalType::AppDataUpdate],
        &[],
    ));
    let mut alice_group = MlsGroup::builder()
        .ciphersuite(CS)
        .with_capabilities(caps())
        .with_group_context_extensions(Extensions::single(required).unwrap())
        .with_wire_format_policy(PURE_PLAINTEXT_WIRE_FORMAT_POLICY)
        .use_ratchet_tree_extension(true)
        .build(&alice.provider, &alice.signer, alice_cwk)
        .unwrap();
    let bob_kp = KeyPackage::builder()
        .leaf_node_capabilities(caps())
        .build(CS, &bob.provider, &bob.signer, bob_cwk)
        .unwrap();
    let (_commit, welcome, _gi) = alice_group
        .add_members(
            &alice.provider,
            &alice.signer,
            &[bob_kp.key_package().clone()],
        )
        .unwrap();
    alice_group.merge_pending_commit(&alice.provider).unwrap();
    let join_config = MlsGroupJoinConfig::builder()
        .wire_format_policy(PURE_PLAINTEXT_WIRE_FORMAT_POLICY)
        .use_ratchet_tree_extension(true)
        .build();
    let MlsMessageBodyIn::Welcome(welcome) = wire(&welcome).extract() else {
        panic!("expected a Welcome")
    };
    let bob_group = StagedWelcome::new_from_welcome(&bob.provider, &join_config, welcome, None)
        .unwrap()
        .into_group(&bob.provider)
        .unwrap();
    let mut g = Group {
        alice,
        alice_group,
        bob,
        bob_group,
    };
    // Seed X and Y with data via a valid commit.
    let out = run(
        &mut g,
        false,
        &[],
        &[
            AppDataUpdateProposal::update(X, b"x".to_vec()),
            AppDataUpdateProposal::update(Y, b"y".to_vec()),
        ],
    );
    assert!(matches!(out, Outcome::Accepted(_)), "seed failed: {out:?}");
    g
}

#[derive(Debug)]
enum Outcome {
    /// alice's own commit creation refused the proposal list.
    SenderRefused(String),
    /// bob rejected the commit (stage named).
    Rejected(&'static str, String),
    /// bob staged and merged; dictionary after the commit.
    Accepted(String),
}

fn dict(group: &MlsGroup) -> String {
    match group.extensions().app_data_dictionary() {
        None => "none".into(),
        Some(ext) => {
            let d = ext.dictionary();
            [X, Y, Z]
                .iter()
                .filter_map(|id| {
                    d.get(id)
                        .map(|v| format!("{id:#06x}={:?}", String::from_utf8_lossy(v)))
                })
                .collect::<Vec<_>>()
                .join(",")
        }
    }
}

/// alice commits `by_ref` proposals (each sent first as its own standalone
/// PublicMessage proposal, stored by bob) plus `inline` proposals, with an
/// optional GroupContextExtensions proposal that re-states the current
/// extensions unchanged. bob processes the commit.
fn run(
    g: &mut Group,
    with_gce: bool,
    by_ref: &[AppDataUpdateProposal],
    inline: &[AppDataUpdateProposal],
) -> Outcome {
    for p in by_ref {
        let (msg, _ref) = g
            .alice_group
            .propose_app_data_update(
                &g.alice.provider,
                &g.alice.signer,
                p.component_id(),
                p.operation().clone(),
            )
            .unwrap();
        let processed = g
            .bob_group
            .process_message(&g.bob.provider, wire(&msg).try_into_protocol_message().unwrap())
            .unwrap();
        match processed.into_content() {
            ProcessedMessageContent::ProposalMessage(qp) => g
                .bob_group
                .store_pending_proposal(g.bob.provider.storage(), *qp)
                .unwrap(),
            _ => panic!("expected a proposal"),
        }
    }

    let current_extensions = g.alice_group.extensions().clone();
    let mut builder = g.alice_group.commit_builder();
    if with_gce {
        builder = builder
            .propose_group_context_extensions(current_extensions)
            .unwrap();
    }
    let mut stage = match builder
        .add_proposals(
            inline
                .iter()
                .cloned()
                .map(|p| Proposal::AppDataUpdate(Box::new(p))),
        )
        .load_psks(g.alice.provider.storage())
    {
        Ok(s) => s,
        Err(e) => return Outcome::SenderRefused(format!("{e:?}")),
    };
    let props: Vec<_> = stage.app_data_update_proposals().cloned().collect();
    let changes = naive_updates(stage.app_data_dictionary_updater(), props.iter());
    stage.with_app_data_dictionary_updates(changes);
    let bundle = match stage
        .build(
            g.alice.provider.rand(),
            g.alice.provider.crypto(),
            &g.alice.signer,
            |_| true,
        )
        .map_err(|e| format!("{e:?}"))
        .and_then(|s| {
            s.stage_commit(&g.alice.provider)
                .map_err(|e| format!("{e:?}"))
        }) {
        Ok(b) => b,
        Err(e) => return Outcome::SenderRefused(e),
    };
    let (commit, _, _) = bundle.into_contents();

    // ---- RECEIVER ----
    let processed = match g
        .bob_group
        .process_message(&g.bob.provider, wire(&commit).try_into_protocol_message().unwrap())
    {
        Ok(p) => p,
        Err(e) => {
            g.alice_group
                .clear_pending_commit(g.alice.provider.storage())
                .unwrap();
            return Outcome::Rejected("process_message", format!("{e:?}"));
        }
    };
    let unresolved = match processed.into_content() {
        ProcessedMessageContent::UnresolvedAppDataCommit(u) => u,
        _ => panic!("expected UnresolvedAppDataCommit"),
    };
    let changes = naive_updates(
        g.bob_group.app_data_dictionary_updater(),
        unresolved.app_data_update_proposals(),
    );
    match g
        .bob_group
        .stage_app_data_commit(&g.bob.provider, *unresolved, changes)
    {
        Err(e) => {
            g.alice_group
                .clear_pending_commit(g.alice.provider.storage())
                .unwrap();
            Outcome::Rejected("stage_app_data_commit", format!("{e:?}"))
        }
        Ok(staged) => {
            g.bob_group
                .merge_staged_commit(&g.bob.provider, staged)
                .unwrap();
            g.alice_group
                .merge_pending_commit(&g.alice.provider)
                .unwrap();
            assert_eq!(
                g.alice_group.epoch_authenticator().as_slice(),
                g.bob_group.epoch_authenticator().as_slice(),
                "alice and bob diverged"
            );
            Outcome::Accepted(dict(&g.bob_group))
        }
    }
}

struct Case {
    name: &'static str,
    spec_valid: bool,
    with_gce: bool,
    by_ref: Vec<AppDataUpdateProposal>,
    inline: Vec<AppDataUpdateProposal>,
}

fn rm(id: u16) -> AppDataUpdateProposal {
    AppDataUpdateProposal::remove(id)
}
fn up(id: u16, d: &[u8]) -> AppDataUpdateProposal {
    AppDataUpdateProposal::update(id, d.to_vec())
}

fn main() {
    let tree = env!("CARGO_PKG_NAME");
    let cases = vec![
        Case {
            name: "ctl-1  remove(X) [X has data]",
            spec_valid: true,
            with_gce: false,
            by_ref: vec![],
            inline: vec![rm(X)],
        },
        Case {
            name: "a      remove(X) by-ref + remove(X) inline",
            spec_valid: false,
            with_gce: false,
            by_ref: vec![rm(X)],
            inline: vec![rm(X)],
        },
        Case {
            name: "b      remove(X) + update(X)",
            spec_valid: false,
            with_gce: false,
            by_ref: vec![],
            inline: vec![rm(X), up(X, b"u")],
        },
        Case {
            name: "c      remove(Z) [Z has no data]",
            spec_valid: false,
            with_gce: false,
            by_ref: vec![],
            inline: vec![rm(Z)],
        },
        Case {
            name: "d1     remove(X) ok, then remove(Y)+update(Y)",
            spec_valid: false,
            with_gce: false,
            by_ref: vec![],
            inline: vec![rm(X), rm(Y), up(Y, b"u")],
        },
        Case {
            name: "d2     remove(X) ok, then remove(Z) [no data]",
            spec_valid: false,
            with_gce: false,
            by_ref: vec![],
            inline: vec![rm(X), rm(Z)],
        },
        Case {
            name: "ctl-b  as b, plus GCE carrying unchanged dict",
            spec_valid: false,
            with_gce: true,
            by_ref: vec![],
            inline: vec![rm(X), up(X, b"u")],
        },
        Case {
            name: "ctl-c  as c, plus GCE carrying unchanged dict",
            spec_valid: false,
            with_gce: true,
            by_ref: vec![],
            inline: vec![rm(Z)],
        },
    ];
    println!("tree: {tree}");
    let mut deviations = 0;
    for c in cases {
        let mut g = setup();
        let out = run(&mut g, c.with_gce, &c.by_ref, &c.inline);
        let accepted = matches!(out, Outcome::Accepted(_));
        let ok = accepted == c.spec_valid;
        if !ok {
            deviations += 1;
        }
        println!(
            "{:<48} | §4.7: {:<7} | OpenMLS: {:?} | {}",
            c.name,
            if c.spec_valid { "valid" } else { "INVALID" },
            out,
            if ok { "matches spec" } else { "DEVIATES" }
        );
    }
    println!("deviations: {deviations}");
}
